sys_variable_value.value:
(function execute(inputs, outputs) {

    var parsedDate1 = new GlideDateTime(inputs.trainingDayStg);  
    parsedDate1.addDaysUTC(-1);  // Subtrai um dia no horário UTC
    parsedDate1.setDisplayValue(parsedDate1.getDate().toString() + " 00:00:00");  // Ajusta para 00:00:00

    var today = new GlideDateTime();
    today.setDisplayValue(today.getDate().toString() + " 00:00:00");  // Ajusta para 00:00:00

    outputs.comparated_dates = parsedDate1 > today;

})(inputs, outputs);

